async function loadDashboard(){const workspaceId=activeWorkspace().id;try{const data=await api(`/api/workspaces/${encodeURIComponent(workspaceId)}/overview`);if(activeWorkspace().id!==workspaceId)return;document.querySelector('#metric-confirmed').textContent=Number(data.confirmed).toLocaleString('pt-BR');document.querySelector('#metric-sent').textContent=Number(data.sent).toLocaleString('pt-BR');document.querySelector('#metric-open').textContent=overviewRate(data.opened,data.sent);document.querySelector('#metric-open-foot').textContent=data.sent?`${data.opened} mensagem(ns) com abertura`:'Nenhum envio ainda';document.querySelector('#metric-bounce').textContent=overviewRate(data.bounced,data.sent);const next=document.querySelector('#overview-next');next.textContent=data.next?`${data.next.name} · ${new Date(data.next.at).toLocaleString('pt-BR')}`:'Nenhuma mensagem aguardando.';const body=document.querySelector('#overview-campaigns');body.innerHTML=data.campaigns.length?data.campaigns.map(row=>`<tr><td>${escapeText(row.name)}</td><td>${row.sent}</td><td>${row.opened} <small>${overviewRate(row.opened,row.sent)}</small></td><td>${row.clicked}</td></tr>`).join(''):'<tr><td colspan="4" class="empty-contacts">Nenhuma campanha neste workspace.</td></tr>'}catch(error){const body=document.querySelector('#overview-campaigns');if(body)body.innerHTML=`<tr><td colspan="4">${escapeText(error.message)}</td></tr>`}}
