function formsPage(){return `<div class="form-builder-grid"><section class="panel form-editor"><div class="panel-header"><div><div class="panel-title">Configurar formulário</div><div class="panel-subtitle">Escolha opt-in simples ou confirmação por e-mail; o consentimento explícito continua obrigatório.</div></div></div><form id="signup-form-editor"><div class="form-editor-fields"><label>Nome interno<input name="name" maxlength="80" required placeholder="Ex.: Captura da página Forex"></label><label>Título exibido<input name="title" maxlength="120" required placeholder="Receba nossas novidades"></label><label class="full">Descrição<textarea name="description" maxlength="300" rows="2" placeholder="O que a pessoa vai receber ao se cadastrar?"></textarea></label><label>Texto do botão<input name="buttonLabel" maxlength="40" required value="Quero receber"></label><label class="checkline"><input name="collectName" type="checkbox"> Pedir nome</label><label class="checkline"><input name="collectPhone" type="checkbox"> Pedir telefone</label><label class="checkline"><input name="phoneRequired" type="checkbox" disabled> Telefone obrigatório</label><p class="form-phone-note full">Se usar o telefone em WhatsApp ou SMS, explique esse uso no texto de consentimento.</p><label class="checkline"><input name="doubleOptIn" type="checkbox" checked> Confirmar inscrição por e-mail (double opt-in)</label><fieldset class="form-colors full"><legend>Aparência do formulário</legend><label>Fundo da página<input type="color" name="pageColor" value="#f5f8f6"></label><label>Fundo do formulário<input type="color" name="cardColor" value="#ffffff"></label><label>Texto<input type="color" name="textColor" value="#20352c"></label><label>Fundo do botão<input type="color" name="buttonColor" value="#176b50"></label><label>Texto do botão<input type="color" name="buttonTextColor" value="#ffffff"></label></fieldset><label class="full">Texto de consentimento<textarea name="consentText" maxlength="300" rows="3" required>Quero receber e-mails sobre este produto. Posso cancelar a inscrição quando quiser.</textarea></label></div><div class="form-tag-field"><strong>Tags aplicadas aos novos contatos</strong><div id="form-tag-options" class="tag-checkboxes"><span class="tag-empty">Carregando tags…</span></div></div><div class="form-actions"><button type="button" class="button secondary" id="form-reset">Novo formulário</button><button type="submit" class="button primary">Salvar formulário</button></div></form></section><section class="panel form-preview-panel"><div class="panel-header"><div><div class="panel-title">Prévia</div><div class="panel-subtitle">O teste segue o modo escolhido. Com double opt-in, a confirmação sai pelo provedor já configurado.</div></div></div><div id="form-preview"></div><p id="form-preview-feedback" class="form-feedback" role="status"></p></section></div><section class="panel saved-forms-panel"><div class="panel-header"><div><div class="panel-title">Formulários salvos</div><div class="panel-subtitle">Cada formulário pertence apenas a este workspace.</div></div></div><div id="signup-form-list" class="saved-form-list">Carregando…</div><div class="form-embed"><label for="form-embed-code">Código para incorporar</label><textarea id="form-embed-code" rows="2" readonly placeholder="Salve um formulário para gerar o código"></textarea><button type="button" class="button secondary" id="copy-form-embed" disabled>Copiar código</button></div><p class="local-embed-note">O endereço de prévia usa este computador. Para incorporar o formulário em um site, o SendMaster precisará estar hospedado em um endereço público com HTTPS.</p></section>`}
function formTagCheckboxes(selected=[]){return workspaceTags.length?workspaceTags.map(tag=>`<label><input type="checkbox" name="formTagIds" value="${escapeText(tag.id)}" ${selected.includes(tag.id)?'checked':''}><span>${escapeText(tag.name)}</span></label>`).join(''):'<span class="tag-empty">Crie tags em Contatos para aplicá-las aos cadastros.</span>'}
function safeFormColor(value,fallback){return /^#[0-9a-f]{6}$/i.test(value||'')?value:fallback}
function formDdiOptions(){return [['🇧🇷 +55','55'],['🇺🇸 +1','1'],['🇵🇹 +351','351'],['🇬🇧 +44','44'],['🇪🇸 +34','34'],['🇫🇷 +33','33'],['🇩🇪 +49','49'],['🇮🇹 +39','39'],['🇦🇷 +54','54'],['🇺🇾 +598','598'],['🇨🇱 +56','56'],['🇨🇴 +57','57'],['🇵🇪 +51','51'],['🇲🇽 +52','52'],['🇮🇪 +353','353'],['🇨🇭 +41','41'],['🇦🇺 +61','61'],['🇯🇵 +81','81'],['🇨🇳 +86','86']].map(([label,value])=>`<option value="${value}" ${value==='55'?'selected':''}>${label}</option>`).join('')}
function renderFormPreview(){const form=document.querySelector('#signup-form-editor');if(!form)return;const data=Object.fromEntries(new FormData(form).entries());const preview=document.querySelector('#form-preview');const page=safeFormColor(data.pageColor,'#f5f8f6'),card=safeFormColor(data.cardColor,'#ffffff'),text=safeFormColor(data.textColor,'#20352c'),button=safeFormColor(data.buttonColor,'#176b50'),buttonText=safeFormColor(data.buttonTextColor,'#ffffff');const required=form.elements.namedItem('phoneRequired').checked;preview.innerHTML=`<div class="signup-preview" style="--form-page:${page};--form-card:${card};--form-text:${text};--form-button:${button};--form-button-text:${buttonText}"><div class="signup-preview-card"><div class="preview-brand">SENDMASTER · ${escapeText(activeWorkspace().name)}</div><h2>${escapeText(data.title||'Título do formulário')}</h2><p>${escapeText(data.description||'A descrição aparecerá aqui.')}</p><form id="signup-preview-form"><label>E-mail<input type="email" name="email" placeholder="voce@exemplo.com" required maxlength="254"></label>${form.elements.namedItem('collectName').checked?'<label>Nome<input name="name" type="text" placeholder="Seu nome" maxlength="120"></label>':''}${form.elements.namedItem('collectPhone').checked?`<label>Telefone${required?'':' (opcional)'}<span class="preview-phone-entry"><select name="ddi" aria-label="Código do país">${formDdiOptions()}</select><input name="phone_raw" type="tel" autocomplete="tel" placeholder="(11) 99999-9999" maxlength="40" ${required?'required':''}></span></label>`:''}<label class="preview-consent"><input type="checkbox" name="consent" required><span>${escapeText(data.consentText||'Texto de consentimento')}</span></label><button class="button primary" ${editingFormId?'':'disabled'}>${escapeText(data.buttonLabel||'Quero receber')}</button></form>${editingFormId?'':'<small>Salve o formulário para testar o cadastro.</small>'}</div></div>`}
function renderSavedForms(){const list=document.querySelector('#signup-form-list');if(!list)return;list.innerHTML=workspaceForms.length?workspaceForms.map(form=>`<div class="saved-form-row"><div><strong>${escapeText(form.name)}</strong><span>${escapeText(form.title)}</span></div><button class="button secondary" data-edit-form="${escapeText(form.id)}">Editar</button><button class="button secondary" data-delete-form="${escapeText(form.id)}">Excluir</button></div>`).join(''):'<p class="tag-empty">Nenhum formulário salvo neste workspace.</p>';const selected=workspaceForms.find(form=>form.id===editingFormId);const code=document.querySelector('#form-embed-code');const copy=document.querySelector('#copy-form-embed');if(selected){const src=`${location.origin}/forms/${selected.id}`;code.value=`<iframe src="${src}" title="${escapeText(selected.title)}" width="100%" height="520" style="border:0" loading="lazy"></iframe>`;copy.disabled=false}else{code.value='';copy.disabled=true}}
async function refreshForms(){const workspaceId=activeWorkspace().id;try{const [result,tags]=await Promise.all([api(`/api/workspaces/${encodeURIComponent(workspaceId)}/forms`),api(`/api/workspaces/${encodeURIComponent(workspaceId)}/tags`)]);if(activeWorkspace().id!==workspaceId)return;workspaceForms=result.forms;workspaceTags=tags.tags;document.querySelector('#form-tag-options').innerHTML=formTagCheckboxes(workspaceForms.find(form=>form.id===editingFormId)?.tagIds||[]);renderSavedForms();renderFormPreview()}catch(error){toast(error.message)}}
function loadSignupForm(id){const form=workspaceForms.find(item=>item.id===id);if(!form)return;editingFormId=id;const editor=document.querySelector('#signup-form-editor');for(const key of ['name','title','description','buttonLabel','consentText','pageColor','cardColor','textColor','buttonColor','buttonTextColor'])editor.elements.namedItem(key).value=form[key];editor.elements.namedItem('collectName').checked=form.collectName;editor.elements.namedItem('collectPhone').checked=form.collectPhone;editor.elements.namedItem('phoneRequired').checked=form.phoneRequired;editor.elements.namedItem('phoneRequired').disabled=!form.collectPhone;editor.elements.namedItem('doubleOptIn').checked=form.doubleOptIn;document.querySelector('#form-tag-options').innerHTML=formTagCheckboxes(form.tagIds);document.querySelector('#form-preview-feedback').textContent='';renderSavedForms();renderFormPreview()}
function contactsPage(){return `
<section class="panel contact-form-panel"><div class="panel-header"><div><div class="panel-title">Adicionar contato</div><div class="panel-subtitle">Novos contatos começam como pendentes e não entram em campanhas até o consentimento ser registrado.</div></div></div><form id="contact-form"><div class="contact-form-grid"><label>Nome<input name="name" placeholder="Nome do contato" maxlength="120"></label><label>E-mail<input id="contact-email" name="email" type="email" placeholder="nome@dominio.com" required maxlength="254"></label><label>Telefone<input name="phone" type="tel" placeholder="+55 (11) 99999-9999" maxlength="40"></label><label>Origem<input name="source" placeholder="Ex.: formulário do site, importação" value="manual" maxlength="120"></label><label>Status de consentimento<select name="status"><option value="pending">Pendente de confirmação</option><option value="confirmed">Consentimento confirmado</option><option value="unsubscribed">Descadastrado</option></select></label><label class="consent-evidence-label" hidden>Como o consentimento foi obtido?<input name="consentEvidence" placeholder="Ex.: formulário X, data e contexto" maxlength="240"></label><div class="contact-tag-field"><span>Tags</span><div id="contact-tag-options" class="tag-checkboxes"><small>Crie tags para classificá-los.</small></div></div></div><div class="contact-form-footer"><span>Contatos descadastrados, bounced ou com reclamação ficam suprimidos.</span><button type="submit" class="button primary">Salvar contato</button></div></form></section>
<section class="panel csv-import-panel"><div class="panel-header"><div><div class="panel-title">Importar contatos por CSV</div><div class="panel-subtitle">A importação mantém todos os contatos pendentes. Use uma coluna de e-mail e, se quiser, nome e origem.</div></div><button type="button" class="button secondary" id="csv-template-download">Baixar modelo CSV</button></div><div class="csv-import-controls"><label for="contacts-csv">Arquivo CSV<input id="contacts-csv" type="file" accept=".csv,text/csv"></label><button type="button" class="button primary" id="csv-import-button" disabled>Importar contatos</button></div><p id="csv-import-feedback" class="csv-import-feedback">Aceita até 1.000 linhas ou 700 KB por vez. E-mails inválidos e repetidos serão informados antes da importação.</p></section>
<section class="panel audience-tags-panel"><div class="panel-header"><div><div class="panel-title">Tags do workspace</div><div class="panel-subtitle">Organize os contatos com categorias próprias deste produto.</div></div></div><form id="tag-form" class="tag-create-form"><label for="new-tag-name">Nova tag<input id="new-tag-name" name="name" placeholder="Ex.: Cliente, Forex, Webinar" maxlength="40" required></label><button type="submit" class="button secondary">Criar tag</button></form><div id="tag-list" class="tag-list"></div></section>
<section class="panel contact-list-panel"><div class="panel-header"><div><div class="panel-title">Audiência deste workspace</div><div class="panel-subtitle" id="contact-count">Carregando contatos…</div></div><label class="contact-search"><span>Buscar</span><input id="contact-search" type="search" placeholder="Nome, e-mail ou telefone"></label></div><div class="segment-filterbar"><label>Status<select id="filter-status"><option value="">Todos</option><option value="confirmed">Consentimento confirmado</option><option value="pending">Pendente</option><option value="unsubscribed">Descadastrado</option><option value="bounced">Bounce</option><option value="complained">Reclamação</option></select></label><label>Origem<select id="filter-source"><option value="">Todas</option></select></label><label>Tag<select id="filter-tag"><option value="">Todas</option></select></label><label>Segmento salvo<select id="saved-segment"><option value="">Filtros atuais</option></select></label><button type="button" class="button secondary" id="save-segment">Salvar segmento</button><button type="button" class="button secondary" id="delete-segment" disabled>Excluir</button></div><div class="table-scroll"><table class="table"><thead><tr><th>CONTATO</th><th>ORIGEM</th><th>TAGS</th><th>CONSENTIMENTO</th><th>CADASTRADO</th></tr></thead><tbody id="contact-rows"><tr><td colspan="5">Carregando…</td></tr></tbody></table></div></section><section class="panel integration-note"><div class="panel-title">Pronto para conversar com outros sistemas</div><p>Cada contato tem um ID estável e pode receber identificadores externos, como o ID do WhatsApp ou do rastreador. Alterações geram eventos consultáveis pela API local; nenhum outro sistema acessa diretamente o arquivo do banco.</p></section>`}
function parseCsvMatrix(text,delimiter){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const char=text[i];if(char==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else if(quoted){quoted=false}else if(cell===''){quoted=true}else throw new Error('Confira as aspas do arquivo CSV.')}else if(char===delimiter&&!quoted){row.push(cell);cell=''}else if((char==='\n'||char==='\r')&&!quoted){if(char==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(value=>value.trim()))rows.push(row);row=[];cell=''}else{cell+=char}}if(quoted)throw new Error('Há uma aspa sem fechamento no arquivo CSV.');if(cell.length||row.length){row.push(cell);if(row.some(value=>value.trim()))rows.push(row)}return rows}
function readContactsCsv(text){text=text.replace(/^\uFEFF/,'');const firstLine=text.split(/\r?\n/,1)[0];let quoted=false,commas=0,semicolons=0;for(let i=0;i<firstLine.length;i++){if(firstLine[i]==='"'){if(quoted&&firstLine[i+1]==='"')i++;else quoted=!quoted}else if(!quoted&&firstLine[i]===',')commas++;else if(!quoted&&firstLine[i]===';')semicolons++}const rows=parseCsvMatrix(text,semicolons>commas?';':',');if(rows.length<2)throw new Error('O CSV precisa ter um cabeçalho e pelo menos uma linha.');const normalize=value=>value.trim().toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g,'');const headers=rows.shift().map(normalize);const emailIndex=headers.findIndex(value=>['email','e-mail','mail'].includes(value));if(emailIndex<0)throw new Error('Não encontrei a coluna de e-mail. Use “email” ou “e-mail” no cabeçalho.');const nameIndex=headers.findIndex(value=>['nome','name'].includes(value));const sourceIndex=headers.findIndex(value=>['origem','source'].includes(value));if(rows.length>1000)throw new Error('O arquivo tem mais de 1.000 linhas. Divida em arquivos menores.');const contacts=[],seen=new Set();let invalid=0,duplicates=0;for(const row of rows){const email=(row[emailIndex]||'').trim();if(!email&&!row.some(value=>value.trim()))continue;if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)||email.length>254){invalid++;continue}const normalized=email.toLowerCase();if(seen.has(normalized)){duplicates++;continue}seen.add(normalized);contacts.push({email,name:nameIndex<0?'':(row[nameIndex]||'').trim().slice(0,120),source:sourceIndex<0?'importação CSV':(row[sourceIndex]||'').trim().slice(0,120)||'importação CSV'})}return{contacts,invalid,duplicates}}
function downloadCsvTemplate(){const blob=new Blob(['email,nome,origem\r\n'],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='modelo-contatos-sendmaster.csv';link.click();URL.revokeObjectURL(url)}
async function importCsvContacts(){if(!pendingCsvImport?.contacts.length)return;const button=document.querySelector('#csv-import-button');button.disabled=true;button.textContent='Importando…';try{const workspaceId=activeWorkspace().id;const result=await api(`/api/workspaces/${encodeURIComponent(workspaceId)}/contacts/import`,{method:'POST',body:JSON.stringify({contacts:pendingCsvImport.contacts})});const report=`Importados: ${result.imported}. Já existentes ignorados: ${result.duplicates}. Repetidos no arquivo: ${pendingCsvImport.duplicates}. Linhas inválidas: ${pendingCsvImport.invalid}.`;document.querySelector('#csv-import-feedback').textContent=report;document.querySelector('#contacts-csv').value='';pendingCsvImport=null;toast(`${result.imported} contato(s) importado(s), todos pendentes.`);await loadContacts(document.querySelector('#contact-search').value)}catch(error){document.querySelector('#csv-import-feedback').textContent=error.message;button.disabled=false;button.textContent='Importar contatos'}}function segmentFilters(){return{search:document.querySelector('#contact-search')?.value.trim()||'',status:document.querySelector('#filter-status')?.value||'',source:document.querySelector('#filter-source')?.value||'',tagId:document.querySelector('#filter-tag')?.value||''}}
function tagCheckboxes(selected=[]){return workspaceTags.length?workspaceTags.map(tag=>`<label><input type="checkbox" name="tagIds" value="${escapeText(tag.id)}" ${selected.includes(tag.id)?'checked':''}><span>${escapeText(tag.name)}</span></label>`).join(''):'<small>Nenhuma tag criada ainda.</small>'}
function renderAudienceTagOptions(){const container=document.querySelector('#contact-tag-options');if(container)container.innerHTML=tagCheckboxes();const tagSelect=document.querySelector('#filter-tag');if(tagSelect){const selected=tagSelect.value;tagSelect.innerHTML='<option value="">Todas</option>'+workspaceTags.map(tag=>`<option value="${escapeText(tag.id)}">${escapeText(tag.name)}</option>`).join('');tagSelect.value=selected}}
function renderTagList(){const container=document.querySelector('#tag-list');if(!container)return;container.innerHTML=workspaceTags.length?workspaceTags.map(tag=>`<span class="tag-chip">${escapeText(tag.name)}<button type="button" data-delete-tag="${escapeText(tag.id)}" aria-label="Excluir tag ${escapeText(tag.name)}">×</button></span>`).join(''):'<span class="tag-empty">Nenhuma tag criada neste workspace.</span>';renderAudienceTagOptions()}
function renderSourceOptions(){const select=document.querySelector('#filter-source');if(!select)return;const selected=select.value;select.innerHTML='<option value="">Todas</option>'+workspaceSources.map(source=>`<option value="${escapeText(source)}">${escapeText(source)}</option>`).join('');select.value=selected}
function renderSegmentOptions(){const select=document.querySelector('#saved-segment');if(!select)return;const selected=select.value;select.innerHTML='<option value="">Filtros atuais</option>'+workspaceSegments.map(segment=>`<option value="${escapeText(segment.id)}">${escapeText(segment.name)}</option>`).join('');select.value=selected;document.querySelector('#delete-segment').disabled=!selected}
async function refreshAudienceData(){const workspaceId=activeWorkspace().id;try{const [tagResult,segmentResult,sourceResult]=await Promise.all([api(`/api/workspaces/${encodeURIComponent(workspaceId)}/tags`),api(`/api/workspaces/${encodeURIComponent(workspaceId)}/segments`),api(`/api/workspaces/${encodeURIComponent(workspaceId)}/contact-sources`)]);if(activeWorkspace().id!==workspaceId)return;workspaceTags=tagResult.tags;workspaceSegments=segmentResult.segments;workspaceSources=sourceResult.sources;renderTagList();renderSourceOptions();renderSegmentOptions();await loadContacts()}catch(error){toast(error.message)}}
async function loadContacts(){const workspaceId=activeWorkspace().id;const body=document.querySelector('#contact-rows');if(!body)return;const filters=segmentFilters();const params=new URLSearchParams();if(filters.search)params.set('q',filters.search);if(filters.status)params.set('status',filters.status);if(filters.source)params.set('source',filters.source);if(filters.tagId)params.set('tagId',filters.tagId);try{const result=await api(`/api/workspaces/${encodeURIComponent(workspaceId)}/contacts?${params}`);if(activeWorkspace().id!==workspaceId)return;document.querySelector('#contact-count').textContent=`${result.contacts.length} contato(s) neste segmento`;body.innerHTML=result.contacts.length?result.contacts.map(contact=>`<tr><td><strong>${escapeText(contact.name||'Sem nome')}</strong><small class="contact-email">${escapeText(contact.email)}</small>${contact.phone?`<small class="contact-email">${escapeText(contact.phone)}</small>`:''}</td><td>${escapeText(contact.source)}</td><td><div class="contact-tag-pills">${(contact.tags||[]).map(tag=>`<span class="tag-pill">${escapeText(tag.name)}</span>`).join('')||'<span class="tag-empty">—</span>'}<details class="contact-tag-editor"><summary>Editar</summary><form class="contact-tag-form" data-contact-id="${escapeText(contact.id)}"><div class="tag-checkboxes">${tagCheckboxes((contact.tags||[]).map(tag=>tag.id))}</div><button class="button secondary" type="submit">Salvar tags</button></form></details></div></td><td><span class="pill ${contact.status==='confirmed'?'status-active':contact.status==='pending'?'status-pending':'status-suppressed'}">${contactStatusLabel(contact.status)}</span></td><td>${new Date(contact.createdAt).toLocaleDateString('pt-BR')}</td></tr>`).join(''):'<tr><td colspan="5" class="empty-contacts">Nenhum contato corresponde a estes filtros.</td></tr>'}catch(error){body.innerHTML=`<tr><td colspan="5">${escapeText(error.message)}</td></tr>`}}
function contactStatusLabel(status){return({pending:'Pendente',confirmed:'Consentimento confirmado',unsubscribed:'Descadastrado',bounced:'Bounce',complained:'Reclamação'})[status]||status}
function domainSettings(){const d=getDomains();return `<section class="panel domain-panel"><div class="panel-header"><div><div class="panel-title">Domínios deste workspace</div><div class="panel-subtitle">Separados por produto para manter identidade e reputação organizadas.</div></div><span class="badge">DNS pendente</span></div><form id="domain-form"><div class="domain-fields"><label>Subdomínio de envio<input name="sending" type="text" value="${escapeText(d.sending||'')}" placeholder="mail.seudominio.com" required><small>Usado na autenticação do remetente e nas mensagens deste produto.</small></label><label>Subdomínio de links rastreáveis<input name="tracking" type="text" value="${escapeText(d.tracking||'')}" placeholder="links.seudominio.com" required><small>Usado como domínio de destino ao registrar cliques nos links.</small></label></div><div class="wizard-note"><span>i</span><span>Recomendação: use subdomínios distintos sob o domínio da mesma marca. O provedor de envio fornecerá os registros DNS exatos de SPF, DKIM e retorno; não vamos inventá-los.</span></div><div class="domain-actions"><span id="domain-state">${d.sending&&d.tracking?'Salvo neste workspace · aguardando configuração DNS':'Ainda não configurado'}</span><button type="submit" class="button primary">Salvar domínios</button></div></form></section><section class="panel domain-next"><div class="panel-title">Próximo passo: autenticar o envio</div><p>Depois de escolher o provedor, vamos obter os valores DNS que ele exige e verificar se os registros foram publicados. A verificação real ainda não está conectada nesta versão local.</p><div class="domain-record"><span>SPF</span><strong>Será informado pelo provedor</strong><i>Pendente</i></div><div class="domain-record"><span>DKIM</span><strong>Será informado pelo provedor</strong><i>Pendente</i></div><div class="domain-record"><span>DMARC</span><strong>Definiremos com base no domínio autenticado</strong><i>Pendente</i></div></section>`}
function view(key){let p=pages[key]||pages.inicio;document.querySelector('#crumb').textContent=p.title;document.title=`SendMaster — ${p.title}`;document.querySelectorAll('.nav-item').forEach(a=>a.classList.toggle('active',a.dataset.view===key));let body=key==='inicio'?dashboard():key==='entregabilidade'?domainSettings():key==='contatos'?contactsPage():key==='formularios'?formsPage():key==='integracoes'?integrationsPage():`<section class="page-placeholder"><div><div class="placeholder-icon">${key==='campanhas'?'✉':'✦'}</div><h2>Seu espaço de ${p.title.toLowerCase()}</h2><p>Esta área será construída na próxima etapa. A navegação e a direção visual já estão preparadas para evoluirmos juntos.</p><button class="button primary" data-action="${key}">${p.action}</button></div></section>`;app.innerHTML=`<div class="page-head"><div><div class="eyebrow">${p.kicker}</div><h1>${p.title}</h1><p>${p.subtitle}</p></div>${['entregabilidade','contatos','formularios','integracoes'].includes(key)?'':`<button class="button primary" data-action="${key}">${p.action}</button>`}</div>${body}`;if(key==='entregabilidade'){document.querySelector('#domain-form').addEventListener('submit',async e=>{e.preventDefault();const form=new FormData(e.currentTarget);const domains={sending:String(form.get('sending')).trim().toLowerCase(),tracking:String(form.get('tracking')).trim().toLowerCase()};if(!validDomain(domains.sending)||!validDomain(domains.tracking)){toast('Informe domínios válidos, sem https:// ou caminhos.');return}try{await api(`/api/workspaces/${encodeURIComponent(activeWorkspace().id)}/domains`,{method:'PUT',body:JSON.stringify(domains)});localStorage.setItem(`sendmaster.domains.v1.${activeWorkspace().id}`,JSON.stringify(domains));document.querySelector('#domain-state').textContent='Salvo neste workspace · aguardando configuração DNS';toast('Domínios salvos neste workspace.')}catch(error){toast(error.message)}})}if(key==='contatos'){
 const workspaceId=activeWorkspace().id;const form=document.querySelector('#contact-form');const status=form.elements.namedItem('status');const evidence=form.querySelector('.consent-evidence-label');evidence.hidden=status.value!=='confirmed';status.addEventListener('change',()=>{evidence.hidden=status.value!=='confirmed'});
 form.addEventListener('submit',async e=>{e.preventDefault();const values=new FormData(form);const data=Object.fromEntries(values.entries());const tagIds=values.getAll('tagIds').map(String);try{const result=await api(`/api/workspaces/${encodeURIComponent(workspaceId)}/contacts`,{method:'POST',body:JSON.stringify(data)});if(tagIds.length)await api(`/api/workspaces/${encodeURIComponent(workspaceId)}/contacts/${encodeURIComponent(result.contact.id)}/tags`,{method:'PUT',body:JSON.stringify({tagIds})});form.reset();form.elements.namedItem('source').value='manual';evidence.hidden=true;toast('Contato salvo. Ele não será enviado enquanto estiver pendente.');await refreshAudienceData()}catch(error){toast(error.message)}});
 document.querySelector('#tag-form').addEventListener('submit',async e=>{e.preventDefault();const name=new FormData(e.currentTarget).get('name').toString().trim();try{await api(`/api/workspaces/${encodeURIComponent(workspaceId)}/tags`,{method:'POST',body:JSON.stringify({name})});e.currentTarget.reset();toast('Tag criada neste workspace.');await refreshAudienceData()}catch(error){toast(error.message)}});
 document.querySelector('#tag-list').addEventListener('click',async e=>{const button=e.target.closest('[data-delete-tag]');if(!button)return;if(!confirm('Excluir esta tag também a removerá dos contatos associados. Continuar?'))return;try{await api(`/api/workspaces/${encodeURIComponent(workspaceId)}/tags/${encodeURIComponent(button.dataset.deleteTag)}`,{method:'DELETE'});toast('Tag removida.');await refreshAudienceData()}catch(error){toast(error.message)}});
 document.querySelector('#contact-rows').addEventListener('submit',async e=>{const editor=e.target.closest('.contact-tag-form');if(!editor)return;e.preventDefault();const tagIds=new FormData(editor).getAll('tagIds').map(String);try{await api(`/api/workspaces/${encodeURIComponent(workspaceId)}/contacts/${encodeURIComponent(editor.dataset.contactId)}/tags`,{method:'PUT',body:JSON.stringify({tagIds})});toast('Tags do contato atualizadas.');await loadContacts()}catch(error){toast(error.message)}});
 document.querySelector('#contact-search').addEventListener('input',()=>{document.querySelector('#saved-segment').value='';renderSegmentOptions();loadContacts()});['#filter-status','#filter-source','#filter-tag'].forEach(selector=>document.querySelector(selector).addEventListener('change',()=>{document.querySelector('#saved-segment').value='';renderSegmentOptions();loadContacts()}));
 document.querySelector('#saved-segment').addEventListener('change',e=>{const segment=workspaceSegments.find(item=>item.id===e.target.value);document.querySelector('#delete-segment').disabled=!segment;if(segment){document.querySelector('#contact-search').value=segment.filters.search;document.querySelector('#filter-status').value=segment.filters.status;document.querySelector('#filter-source').value=segment.filters.source;document.querySelector('#filter-tag').value=segment.filters.tagId;loadContacts()}});
 document.querySelector('#save-segment').addEventListener('click',async()=>{const filters=segmentFilters();if(!filters.search&&!filters.status&&!filters.source&&!filters.tagId){toast('Escolha ao menos um filtro antes de salvar o segmento.');return}const name=prompt('Nome deste segmento:','Minha audiência');if(!name?.trim())return;try{const result=await api(`/api/workspaces/${encodeURIComponent(workspaceId)}/segments`,{method:'POST',body:JSON.stringify({name:name.trim(),filters})});workspaceSegments.unshift(result.segment);renderSegmentOptions();document.querySelector('#saved-segment').value=result.segment.id;document.querySelector('#delete-segment').disabled=false;toast('Segmento salvo neste workspace.')}catch(error){toast(error.message)}});
 document.querySelector('#delete-segment').addEventListener('click',async()=>{const id=document.querySelector('#saved-segment').value;if(!id||!confirm('Excluir este segmento salvo?'))return;try{await api(`/api/workspaces/${encodeURIComponent(workspaceId)}/segments/${encodeURIComponent(id)}`,{method:'DELETE'});workspaceSegments=workspaceSegments.filter(segment=>segment.id!==id);document.querySelector('#saved-segment').value='';renderSegmentOptions();toast('Segmento removido.')}catch(error){toast(error.message)}});
 document.querySelector('#csv-template-download').addEventListener('click',downloadCsvTemplate);document.querySelector('#contacts-csv').addEventListener('change',async e=>{const file=e.target.files[0];const feedback=document.querySelector('#csv-import-feedback');const button=document.querySelector('#csv-import-button');pendingCsvImport=null;button.disabled=true;button.textContent='Importar contatos';if(!file){feedback.textContent='Selecione um arquivo CSV.';return}if(file.size>700000){feedback.textContent='O arquivo ultrapassa o limite de 700 KB.';return}try{pendingCsvImport=readContactsCsv(await file.text());const{contacts,invalid,duplicates}=pendingCsvImport;feedback.textContent=`Prévia: ${contacts.length} contato(s) válido(s); ${duplicates} repetido(s) no arquivo; ${invalid} linha(s) inválida(s). Todos serão importados como pendentes.`;button.disabled=!contacts.length}catch(error){feedback.textContent=error.message}});document.querySelector('#csv-import-button').addEventListener('click',importCsvContacts);renderSegmentOptions();void refreshAudienceData()
}if(key==='inicio')void loadDashboard();if(key==='formularios')initSignupForms();if(key==='integracoes')initMailerSettings()}
function initSignupForms(){editingFormId='';const editor=document.querySelector('#signup-form-editor');editor.addEventListener('input',renderFormPreview);editor.addEventListener('change',event=>{if(event.target.name==='collectPhone')editor.elements.namedItem('phoneRequired').disabled=!event.target.checked;if(event.target.name==='collectPhone'&&!event.target.checked)editor.elements.namedItem('phoneRequired').checked=false;renderFormPreview()});editor.addEventListener('submit',async event=>{event.preventDefault();const values=new FormData(editor);const payload={name:String(values.get('name')).trim(),title:String(values.get('title')).trim(),description:String(values.get('description')||'').trim(),buttonLabel:String(values.get('buttonLabel')).trim(),consentText:String(values.get('consentText')).trim(),collectName:values.has('collectName'),collectPhone:values.has('collectPhone'),phoneRequired:values.has('phoneRequired'),doubleOptIn:values.has('doubleOptIn'),pageColor:values.get('pageColor'),cardColor:values.get('cardColor'),textColor:values.get('textColor'),buttonColor:values.get('buttonColor'),buttonTextColor:values.get('buttonTextColor'),tagIds:values.getAll('formTagIds').map(String)};try{const path=`/api/workspaces/${encodeURIComponent(activeWorkspace().id)}/forms${editingFormId?`/${encodeURIComponent(editingFormId)}`:''}`;const result=await api(path,{method:editingFormId?'PUT':'POST',body:JSON.stringify(payload)});editingFormId=result.form.id;await refreshForms();toast('Formulário salvo neste workspace.')}catch(error){toast(error.message)}});document.querySelector('#form-reset').addEventListener('click',()=>{editingFormId='';editor.reset();editor.elements.namedItem('buttonLabel').value='Quero receber';editor.elements.namedItem('doubleOptIn').checked=true;editor.elements.namedItem('collectPhone').checked=false;editor.elements.namedItem('phoneRequired').checked=false;editor.elements.namedItem('phoneRequired').disabled=true;editor.elements.namedItem('pageColor').value='#f5f8f6';editor.elements.namedItem('cardColor').value='#ffffff';editor.elements.namedItem('textColor').value='#20352c';editor.elements.namedItem('buttonColor').value='#176b50';editor.elements.namedItem('buttonTextColor').value='#ffffff';editor.elements.namedItem('consentText').value='Quero receber e-mails sobre este produto. Posso cancelar a inscrição quando quiser.';document.querySelector('#form-preview-feedback').textContent='';document.querySelector('#form-tag-options').innerHTML=formTagCheckboxes();renderSavedForms();renderFormPreview()});document.querySelector('#form-preview').addEventListener('submit',async event=>{if(event.target.id!=='signup-preview-form')return;event.preventDefault();if(!editingFormId)return;const values=new FormData(event.target),feedback=document.querySelector('#form-preview-feedback');try{const result=await api(`/api/forms/${encodeURIComponent(editingFormId)}/submissions`,{method:'POST',body:JSON.stringify({email:values.get('email'),name:values.get('name')||'',phone:(String(values.get('phone_raw')||'').replace(/\D/g,'')?String(values.get('ddi')||'55')+String(values.get('phone_raw')||'').replace(/\D/g,''):''),consent:values.get('consent')==='on'})});feedback.textContent=result.message;event.target.reset()}catch(error){feedback.textContent=error.message}});document.querySelector('#signup-form-list').addEventListener('click',async event=>{const edit=event.target.closest('[data-edit-form]'),remove=event.target.closest('[data-delete-form]');if(edit){loadSignupForm(edit.dataset.editForm);return}if(remove){if(!confirm('Excluir este formulário? Os contatos já cadastrados serão mantidos.'))return;try{await api(`/api/workspaces/${encodeURIComponent(activeWorkspace().id)}/forms/${encodeURIComponent(remove.dataset.deleteForm)}`,{method:'DELETE'});if(editingFormId===remove.dataset.deleteForm)document.querySelector('#form-reset').click();await refreshForms();toast('Formulário excluído.')}catch(error){toast(error.message)}}});document.querySelector('#copy-form-embed').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(document.querySelector('#form-embed-code').value);toast('Código de incorporação copiado.')}catch{toast('Não foi possível copiar; selecione o código e copie manualmente.')}});void refreshForms()}
function getDomains(){try{return JSON.parse(localStorage.getItem(`sendmaster.domains.v1.${activeWorkspace().id}`)||'{}')}catch{return {}}}
async function persistBrief(name,data){const brief={id:crypto.randomUUID(),name:name.trim(),data,updatedAt:new Date().toISOString()};await api(`/api/workspaces/${encodeURIComponent(activeWorkspace().id)}/briefs`,{method:'POST',body:JSON.stringify(brief)});const briefs=getBriefs();briefs.unshift(brief);localStorage.setItem(`sendmaster.briefs.v1.${activeWorkspace().id}`,JSON.stringify(briefs));return brief}
function validDomain(value){return /^(?=.{1,253}$)(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,}$/i.test(value)}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2600)}
function openCopyWizard(){
 const saved=getBriefs();const modal=document.createElement('div');modal.className='modal-backdrop';modal.innerHTML=`<section class="wizard" role="dialog" aria-modal="true" aria-labelledby="wizard-title"><header class="wizard-head"><div><div class="eyebrow">ASSISTENTE DE IA · NOVA CAMPANHA</div><h2 id="wizard-title">Vamos entender seu e-mail</h2><p>Quanto melhor o contexto, mais útil será a primeira versão da copy.</p></div><button class="close-modal" aria-label="Fechar">×</button></header><div class="wizard-progress"><span class="progress-step active"><i>1</i> Contexto</span><b></b><span class="progress-step"><i>2</i> Perspectivas</span><b></b><span class="progress-step"><i>3</i> Revisar</span></div><form id="copy-form"><div class="saved-brief-row"><label>Carregar um brief salvo<select id="saved-brief"><option value="">Começar um novo briefing</option>${saved.map(b=>`<option value="${escapeText(b.id)}">${escapeText(b.name)}</option>`).join('')}</select></label><button type="button" class="button secondary" id="save-brief">Salvar este brief</button></div><div class="wizard-fields"><label>Qual é o objetivo deste e-mail?<select name="goal" required><option value="">Selecione o objetivo</option><option>Apresentar ou vender um produto</option><option>Relacionar e engajar a audiência</option><option>Enviar novidades ou conteúdo</option><option>Convidar para um evento</option><option>Recuperar clientes ou carrinhos</option><option>Outro objetivo</option></select></label><label>Quem vai receber?<input name="audience" required placeholder="Ex.: clientes atuais, leads que baixaram um guia" /></label><label>Sobre qual produto, serviço ou assunto?<input name="subject" required placeholder="Conte o que é e por que importa" /></label><label>O que você quer que a pessoa faça?<input name="action" placeholder="Ex.: conhecer a oferta, responder, acessar um conteúdo" /></label><label>Qual tom combina com sua marca?<select name="tone"><option>Próximo e natural</option><option>Direto e profissional</option><option>Educativo e consultivo</option><option>Leve e bem-humorado</option><option>Inspirador</option></select></label><label>O que a IA deve evitar ou preservar?<input name="constraints" placeholder="Ex.: não prometer resultados; manter o preço e prazo" /></label></div><details class="advanced-brief"><summary>Adicionar contexto (opcional)</summary><div class="wizard-fields"><label>Oferta, benefício ou informação principal<input name="offer" placeholder="O que torna esta mensagem relevante agora?" /></label><label>Alguma prova ou detalhe que deve entrar?<input name="proof" placeholder="Ex.: dado, depoimento autorizado, condição" /></label></div></details><div class="wizard-note"><span>✦</span><span>A copy poderá ser analisada por perspectivas de estratégia, escrita e entregabilidade. Você revisa tudo antes de usar.</span></div><footer class="wizard-footer"><button type="button" class="button secondary close-modal">Cancelar</button><button type="submit" class="button primary">Preparar briefing <span>→</span></button></footer></form></section>`;
 document.body.append(modal);modal.querySelector('input').focus();modal.querySelectorAll('.close-modal').forEach(b=>b.addEventListener('click',()=>modal.remove()));modal.addEventListener('click',e=>{if(e.target===modal)modal.remove()});
 const form=modal.querySelector('#copy-form');modal.querySelector('#saved-brief').addEventListener('change',e=>{const brief=saved.find(b=>b.id===e.target.value);if(brief)Object.entries(brief.data).forEach(([key,value])=>{const field=form.elements.namedItem(key);if(field)field.value=value})});
 modal.querySelector('#save-brief').addEventListener('click',async()=>{const data=Object.fromEntries(new FormData(form).entries());if(!data.goal||!data.audience||!data.subject){toast('Preencha objetivo, público e assunto para salvar o brief.');return}const name=prompt('Nome deste brief reutilizável:','Engajamento de público');if(!name)return;try{await persistBrief(name,data);toast(`Brief “${name.trim()}” salvo neste workspace.`);modal.remove()}catch(error){toast(error.message)}});
 form.addEventListener('submit',e=>{e.preventDefault();const d=new FormData(form);const data=Object.fromEntries(d.entries());modal.querySelector('.wizard-head h2').textContent='Briefing pronto para revisão';modal.querySelector('.wizard-head p').textContent='As perspectivas já estão definidas. A conexão com um provedor vai executar a análise real.';modal.querySelector('.wizard-progress').innerHTML='<span class="progress-step active"><i>✓</i> Contexto</span><b></b><span class="progress-step active"><i>2</i> Perspectivas</span><b></b><span class="progress-step"><i>3</i> Revisar</span>';modal.querySelector('.saved-brief-row').remove();modal.querySelector('.wizard-fields').innerHTML=`<div class="brief-summary"><span>OBJETIVO</span><strong>${escapeText(data.goal)}</strong><span>PÚBLICO</span><strong>${escapeText(data.audience)}</strong><span>PRODUTO / ASSUNTO</span><strong>${escapeText(data.subject)}</strong><span>PRÓXIMA AÇÃO</span><strong>${escapeText(data.action||'A definir')}</strong><span>TOM</span><strong>${escapeText(data.tone)}</strong></div><div class="perspective-list"><div><i>01</i><span><strong>Estrategista</strong><small>Confere objetivo, público e oferta</small></span></div><div><i>02</i><span><strong>Copywriter + editor</strong><small>Cria e refina assunto, prévia e corpo</small></span></div><div><i>03</i><span><strong>Revisor de entregabilidade</strong><small>Aponta riscos e explica o motivo</small></span></div></div><div class="wizard-note"><span>!</span><span>As perspectivas ainda não foram executadas: conecte um provedor de IA para gerar análises reais. Nenhuma copy será enviada automaticamente.</span></div>`;modal.querySelector('.advanced-brief').remove();modal.querySelector('.wizard-footer').innerHTML='<button type="button" class="button secondary close-modal">Fechar</button><button type="button" class="button primary" id="finish-brief">Salvar como modelo reutilizável</button>';modal.querySelectorAll('.close-modal').forEach(b=>b.addEventListener('click',()=>modal.remove()));modal.querySelector('#finish-brief').addEventListener('click',async()=>{const name=prompt('Nome deste brief reutilizável:','Engajamento de público');if(!name)return;try{await persistBrief(name,data);modal.remove();toast(`Brief “${name.trim()}” salvo neste workspace.`)}catch(error){toast(error.message)}})});
}
function getBriefs(){try{return JSON.parse(localStorage.getItem(`sendmaster.briefs.v1.${activeWorkspace().id}`)||'[]')}catch{return []}}
function escapeText(value){return String(value||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
document.querySelector('#workspace-switcher').addEventListener('click',showWorkspaceMenu);
document.addEventListener('click',async e=>{const menu=document.querySelector('#workspace-menu');if(e.target.closest('#create-workspace')){createWorkspace();return}const switcher=e.target.closest('[data-switch-workspace]');if(switcher){try{const state=await api(`/api/workspaces/${encodeURIComponent(switcher.dataset.switchWorkspace)}/active`,{method:'PUT'});cacheState(state);menu?.remove();document.querySelector('#workspace-switcher').setAttribute('aria-expanded','false');renderWorkspace();view('inicio')}catch(error){toast(error.message)}return}if(menu&&!e.target.closest('#workspace-menu')&&!e.target.closest('#workspace-switcher')){menu.remove();document.querySelector('#workspace-switcher').setAttribute('aria-expanded','false')}const nav=e.target.closest('[data-view]');if(nav){e.preventDefault();view(nav.dataset.view);history.replaceState(null,'','#'+nav.dataset.view);return}const go=e.target.closest('[data-go]');if(go){view(go.dataset.go);history.replaceState(null,'','#'+go.dataset.go);return}const action=e.target.closest('[data-action]');if(action){if(action.dataset.action==='inicio'||action.dataset.action==='campanhas')openCopyWizard();else toast(action.dataset.action==='entregabilidade'?'Na próxima etapa vamos conectar e verificar seu domínio.':'A estrutura está pronta para construirmos esta área.')}});
window.addEventListener('hashchange',()=>view(location.hash.slice(1)||'inicio'));
void startApp();

